  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='0.03'/%3E%3C/svg%3E");
  pointer-events: none;
  z-index: 9999;
}

/* Animated gradient background */
.gradient-bg {
  background: linear-gradient(135deg, #0D1B2A 0%, #15295A 50%, #0D1B2A 100%);
  background-size: 200% 200%;
  animation: gradientShift 8s ease infinite;
}

@keyframes gradientShift {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

/* Glow effects */
.glow-teal {
  box-shadow: 0 0 20px rgba(0, 180, 216, 0.3), 0 0 60px rgba(0, 180, 216, 0.1);
}

.glow-green {
  box-shadow: 0 0 20px rgba(108, 194, 74, 0.3), 0 0 60px rgba(108, 194, 74, 0.1);
}

/* Tab underline animation */
.tab-underline {
  position: relative;
}

.tab-underline::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 100%;
  height: 2px;
  background: #00B4D8;
  transform: scaleX(0);
  transition: transform 0.3s ease;
}

.tab-underline.active::after {
  transform: scaleX(1);
}

/* Circular stat animation */
@keyframes statPulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.8; }
}

/* Stagger animation helper */
.stagger-in > * {
  opacity: 0;
  transform: translateY(20px);
  animation: staggerFadeIn 0.5s ease forwards;
}

.stagger-in > *:nth-child(1) { animation-delay: 0.1s; }
.stagger-in > *:nth-child(2) { animation-delay: 0.2s; }
.stagger-in > *:nth-child(3) { animation-delay: 0.3s; }
.stagger-in > *:nth-child(4) { animation-delay: 0.4s; }
.stagger-in > *:nth-child(5) { animation-delay: 0.5s; }
.stagger-in > *:nth-child(6) { animation-delay: 0.6s; }

@keyframes staggerFadeIn {
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Data flow animation for diagrams */
@keyframes dataFlow {
  0% { stroke-dashoffset: 20; }
  100% { stroke-dashoffset: 0; }
}

.data-flow-line {
  stroke-dasharray: 8 4;
  animation: dataFlow 1s linear infinite;
}

/* Progress bar animation */
@keyframes progressFill {
  from { width: 0%; }
}

.progress-bar {
  animation: progressFill 1.5s ease-out forwards;
}

/* Accordion transition */
.accordion-content {
  overflow: hidden;
  transition: max-height 0.3s ease, opacity 0.3s ease;
}

/* Scrollbar styling */
::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-track {
  background: #0D1B2A;
}

::-webkit-scrollbar-thumb {
  background: #1E3A5F;
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: #2A4A6B;
}

