    {
      id: "utilities",
      label: "Utilities",
      content: "Utility companies managing gas distribution and pipeline networks rely on WellStream for land management, regulatory compliance, and infrastructure tracking across distributed assets.",
    },
    {
      id: "solar-wind",
      label: "Solar/Wind",
      content: "Renewable energy operators use WellStream Land tools to manage leases, agreements, and land positions for solar, wind, and geothermal projects. Accelerate project development with streamlined data workflows.",
    },
    {
      id: "mining",
      label: "Mining",
      content: "Mining operations leverage WellStream for environmental compliance, water management, and site activity tracking. Manage complex permitting and reporting requirements with configurable workflows.",
    },
  ],

  platformDiagram: {
    pillars: [
      {
        title: "Well Data Lifecycle",
        description: "Plan, drill, complete, and manage wells from spud to abandonment.",
        products: ["WellView Allez", "RigView", "Well Reliability", "Well Integrity", "WellStream Frac", "SiteView Allez", "SiteView Go", "WellStream Ram", "WellStream Innova", "WellStream Equipment", "WellStream Water", "WellStream Water Go", "WellStream Dashboards"],
      },
