        title: "Production Data Lifecycle",
        description: "Capture, allocate, report, and optimize production volumes.",
        products: ["Production Tracking", "Allocation Management", "Decline Curve Analysis", "Regulatory Reporting", "WellStream Dashboards"],
      },
      {
        title: "Land Data Management",
        description: "Track leases, agreements, obligations, and mineral rights.",
        products: ["Lease Management", "Agreement Tracking", "Obligation Monitoring", "Mineral Rights", "LandView Map"],
      },
    ],
