    { title: "Save Resources", description: "Reduce headcount dedicated to spreadsheet management by consolidating tools into one platform.", icon: "users" },
    { title: "Save Money", description: "Lower total cost of ownership versus maintaining multiple legacy systems and on-premise servers.", icon: "dollar" },
    { title: "Stay Connected", description: "Access your data from any device, anywhere, with cloud-native mobile and desktop applications.", icon: "wifi" },
