    { title: "Get Mobility", description: "Field-ready mobile apps that sync in real time, even in low-connectivity environments.", icon: "smartphone" },
    { title: "Get Real-Time Reporting", description: "Configurable dashboards deliver live KPIs to executives, engineers, and field teams simultaneously.", icon: "bar-chart" },
    { title: "Get Connected", description: "Open APIs, ETL pipelines, and pre-built connectors integrate WellStream with your existing tech stack.", icon: "link" },
  ],

  securityFeatures: [
    { title: "SOC 1 & 2 Certified Compliance", description: "Annual third-party audits verify controls over financial and operational data handling.", icon: "badge-check" },
    { title: "Powered by Microsoft Azure", description: "Enterprise cloud infrastructure with geo-redundant data centers and 99.95% uptime SLA.", icon: "cloud" },
    { title: "Performance Monitoring", description: "Continuous application and infrastructure monitoring with automated alerting and incident response.", icon: "activity" },
    { title: "Single Sign-On (SSO) Authentication", description: "Integrate with your corporate identity provider for seamless, secure access management.", icon: "key" },
    { title: "Security Information and Event Management (SIEM) System", description: "Real-time log aggregation, threat detection, and forensic analysis across all platform components.", icon: "scan-eye" },
  ],

  securityTabs: {
