import { useState } from "react"
import { motion, AnimatePresence } from "framer-motion"
import {
  Clock, Users, DollarSign, Wifi, ShieldCheck,
  Zap, Smartphone, BarChart3, Link2, ChevronDown, ArrowRight, Quote
} from "lucide-react"
import { siteConfig } from "@/config/site"

const benefitIcons: Record<string, React.ReactNode> = {
  clock: <Clock className="w-6 h-6" />,
  users: <Users className="w-6 h-6" />,
  dollar: <DollarSign className="w-6 h-6" />,
  wifi: <Wifi className="w-6 h-6" />,
  shield: <ShieldCheck className="w-6 h-6" />,
}

const accordionIcons: Record<string, React.ReactNode> = {
  zap: <Zap className="w-5 h-5" />,
  shield: <ShieldCheck className="w-5 h-5" />,
  smartphone: <Smartphone className="w-5 h-5" />,
  "bar-chart": <BarChart3 className="w-5 h-5" />,
  link: <Link2 className="w-5 h-5" />,
}

function CircularProgress({ value, label, description }: { value: string; label: string; description: string }) {
  const numericValue = parseInt(value)
  const circumference = 2 * Math.PI * 54
  const progress = (numericValue / 100) * circumference

  return (
    <div className="flex flex-col items-center text-center">
      <div className="relative w-32 h-32 mb-4">
        <svg className="w-full h-full -rotate-90" viewBox="0 0 120 120">
          <circle cx="60" cy="60" r="54" stroke="#1E3A5F" strokeWidth="6" fill="none" />
          <motion.circle
            cx="60" cy="60" r="54"
            stroke="#00B4D8"
            strokeWidth="6"
            fill="none"
            strokeLinecap="round"
            strokeDasharray={circumference}
            initial={{ strokeDashoffset: circumference }}
            whileInView={{ strokeDashoffset: circumference - progress }}
            viewport={{ once: true }}
            transition={{ duration: 1.5, ease: "easeOut" }}
          />
        </svg>
        <div className="absolute inset-0 flex flex-col items-center justify-center">
          <span className="font-heading text-2xl font-bold text-primary">{value}</span>
          <span className="text-[10px] text-muted-foreground uppercase tracking-wider">{label.includes("pursuing") ? "transform" : label.includes("reported") ? "ROI" : "companies"}</span>
        </div>
      </div>
      <p className="text-sm text-muted-foreground max-w-[200px]">{description}</p>
    </div>
  )
}

function AccordionItem({ feature, isOpen, onToggle }: { feature: typeof siteConfig.accordionFeatures[0]; isOpen: boolean; onToggle: () => void }) {
  return (
    <div className="border border-border/50 rounded-xl overflow-hidden">
      <button
        onClick={onToggle}
        className="w-full flex items-center gap-4 p-5 text-left hover:bg-muted/20 transition-colors"
      >
        <div className={`w-10 h-10 rounded-lg flex items-center justify-center flex-shrink-0 transition-colors ${isOpen ? "bg-primary text-primary-foreground" : "bg-primary/10 text-primary"}`}>
          {accordionIcons[feature.icon]}
        </div>
        <span className="font-heading font-semibold text-foreground flex-1">{feature.title}</span>
        <ChevronDown className={`w-5 h-5 text-muted-foreground transition-transform flex-shrink-0 ${isOpen ? "rotate-180" : ""}`} />
      </button>
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.3 }}
          >
            <div className="px-5 pb-5 pl-19 text-muted-foreground leading-relaxed" style={{ paddingLeft: "4.25rem" }}>
              {feature.description}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  )
}

export function PlatformOverviewPage() {
  const [openAccordion, setOpenAccordion] = useState<string | null>("Get Speed")
  const [currentTestimonial, setCurrentTestimonial] = useState(0)

  return (
    <>
      {/* Hero */}
      <section className="relative overflow-hidden gradient-bg py-20 sm:py-28">
        <div className="absolute inset-0">
          <div className="absolute top-10 right-20 w-80 h-80 bg-primary/5 rounded-full blur-3xl" />
        </div>
        <div className="relative max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
          >
            <span className="inline-block text-xs font-semibold tracking-widest text-primary uppercase mb-4">Platform Overview</span>
            <h1 className="font-heading text-4xl sm:text-5xl lg:text-6xl font-bold text-foreground mb-6">
              One Platform.<br /><span className="text-primary">Every Advantage.</span>
            </h1>
            <p className="text-lg text-muted-foreground max-w-2xl mx-auto">
              From well data to production reporting to land management, WellStream unifies your operations in a single, cloud-native platform.
            </p>
          </motion.div>
        </div>
      </section>

      {/* Platform Benefits */}
      <section className="py-20 sm:py-28">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-16">
            <h2 className="font-heading text-3xl sm:text-4xl font-bold text-foreground mb-4">Why WellStream?</h2>
            <p className="text-muted-foreground text-lg max-w-2xl mx-auto">
              The platform purpose-built to save time, reduce costs, and keep your data secure.
            </p>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {siteConfig.platformBenefits.map((benefit, i) => (
              <motion.div
                key={benefit.title}
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ delay: i * 0.1 }}
                className="p-6 rounded-xl border border-border/50 bg-card/30 hover:bg-card/60 hover:border-primary/20 transition-all group"
              >
                <div className="w-12 h-12 rounded-lg bg-primary/10 flex items-center justify-center text-primary mb-4 group-hover:bg-primary/20 transition-colors">
                  {benefitIcons[benefit.icon]}
                </div>
                <h3 className="font-heading font-semibold text-foreground mb-2">{benefit.title}</h3>
                <p className="text-sm text-muted-foreground leading-relaxed">{benefit.description}</p>
              </motion.div>
            ))}
          </div>
        </div>
      </section>

      {/* Stats Section */}
      <section className="py-20 sm:py-28 bg-navy-900 border-y border-border/30">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-16">
            <h2 className="font-heading text-3xl sm:text-4xl font-bold text-foreground mb-4">Proven at Scale</h2>
            <p className="text-muted-foreground text-lg">Trusted by energy operators worldwide.</p>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-8 justify-items-center">
            {siteConfig.stats.map((stat, i) => (
              <motion.div
                key={stat.value}
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ delay: i * 0.15 }}
              >
                <CircularProgress value={stat.value} label={stat.label} description={stat.description} />
              </motion.div>
            ))}
          </div>
        </div>
      </section>

      {/* Implementation Timeline */}
      <section className="py-20 sm:py-28">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-16">
            <h2 className="font-heading text-3xl sm:text-4xl font-bold text-foreground mb-4">Implementation Timeline</h2>
            <p className="text-muted-foreground text-lg">From demo to live — faster than you think.</p>
          </div>
          <div className="max-w-3xl mx-auto space-y-8">
            {siteConfig.implementationTimeline.map((item, i) => (
              <motion.div
                key={item.duration}
                initial={{ opacity: 0, x: -20 }}
                whileInView={{ opacity: 1, x: 0 }}
                viewport={{ once: true }}
                transition={{ delay: i * 0.15 }}
                className="space-y-3"
              >
                <div className="flex items-center justify-between">
                  <span className="font-heading text-xl font-bold text-primary">{item.duration}</span>
                  <span className="text-sm text-muted-foreground">{item.description}</span>
                </div>
                <div className="h-3 rounded-full bg-muted overflow-hidden">
                  <motion.div
                    className="h-full rounded-full bg-gradient-to-r from-teal-500 to-primary"
                    initial={{ width: 0 }}
                    whileInView={{ width: `${item.progress}%` }}
                    viewport={{ once: true }}
                    transition={{ duration: 1.5, ease: "easeOut", delay: 0.3 }}
                  />
                </div>
              </motion.div>
            ))}
          </div>
        </div>
      </section>

      {/* Accordion Features */}
      <section className="py-20 sm:py-28 bg-card border-y border-border/30">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="grid lg:grid-cols-2 gap-12 items-start">
            <div>
              <h2 className="font-heading text-3xl sm:text-4xl font-bold text-foreground mb-4">
                Everything You Need<br /><span className="text-primary">Built In.</span>
              </h2>
              <p className="text-muted-foreground text-lg leading-relaxed">
                WellStream delivers speed, security, mobility, and connectivity out of the box. No add-ons. No compromises.
              </p>
            </div>
            <div className="space-y-3">
              {siteConfig.accordionFeatures.map((feature) => (
                <AccordionItem
                  key={feature.title}
                  feature={feature}
                  isOpen={openAccordion === feature.title}
                  onToggle={() => setOpenAccordion(openAccordion === feature.title ? null : feature.title)}
                />
              ))}
            </div>
          </div>
        </div>
      </section>

      {/* Data Lifecycle Diagram */}
      <section className="py-20 sm:py-28">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-16">
            <h2 className="font-heading text-3xl sm:text-4xl font-bold text-foreground mb-4">Data Lifecycle Coverage</h2>
            <p className="text-muted-foreground text-lg">End-to-end visibility across your entire data journey.</p>
          </div>

          <div className="max-w-4xl mx-auto">
