              {/* Central Flow Line */}
              <line x1="100" y1="250" x2="700" y2="250" stroke="#1E3A5F" strokeWidth="3" />
              <line x1="100" y1="250" x2="700" y2="250" stroke="#00B4D8" strokeWidth="3" strokeDasharray="8 4" className="data-flow-line" opacity="0.6" />

              {/* Stage Circles */}
              {[
                { x: 160, label: "PLAN", sublabel: "Well Design", color: "#00B4D8" },
                { x: 300, label: "DRILL", sublabel: "Rig Operations", color: "#00B4D8" },
                { x: 440, label: "COMPLETE", sublabel: "Frac & Stim", color: "#6CC24A" },
                { x: 580, label: "PRODUCE", sublabel: "Optimization", color: "#6CC24A" },
                { x: 700, label: "MANAGE", sublabel: "Integrity", color: "#00B4D8" },
              ].map((stage) => (
                <g key={stage.label}>
                  <circle cx={stage.x} cy="250" r="36" fill="#0D1B2A" stroke={stage.color} strokeWidth="2" />
