import { useState, type FormEvent } from "react"
import { motion } from "framer-motion"
import { Send, MapPin, Mail, CheckCircle2, Globe } from "lucide-react"
import { siteConfig } from "@/config/site"

interface FormData {
  firstName: string
  lastName: string
  email: string
  company: string
  phone: string
  jobTitle: string
  country: string
  comments: string
}

interface FormErrors {
  [key: string]: string
}

export function RequestDemoPage() {
  const [formData, setFormData] = useState<FormData>({
    firstName: "",
    lastName: "",
    email: "",
    company: "",
    phone: "",
    jobTitle: "",
    country: "",
    comments: "",
  })
  const [errors, setErrors] = useState<FormErrors>({})
  const [submitted, setSubmitted] = useState(false)

  function validate(): FormErrors {
    const errs: FormErrors = {}
    if (!formData.firstName.trim()) errs.firstName = "First name is required"
    if (!formData.lastName.trim()) errs.lastName = "Last name is required"
    if (!formData.email.trim()) {
      errs.email = "Business email is required"
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      errs.email = "Please enter a valid email address"
    }
    if (!formData.company.trim()) errs.company = "Company is required"
    return errs
  }

  function handleSubmit(e: FormEvent) {
    e.preventDefault()
    const validationErrors = validate()
    setErrors(validationErrors)
    if (Object.keys(validationErrors).length === 0) {
      setSubmitted(true)
    }
  }

  function handleChange(field: keyof FormData, value: string) {
    setFormData((prev) => ({ ...prev, [field]: value }))
    if (errors[field]) {
      setErrors((prev) => {
        const next = { ...prev }
        delete next[field]
        return next
      })
    }
  }

  return (
    <>
      {/* Form Section */}
      <section className="py-20 sm:py-28">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="grid lg:grid-cols-2 gap-12 lg:gap-16">
            {/* Left - Info */}
            <div>
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.5 }}
              >
                <span className="inline-block text-xs font-semibold tracking-widest text-primary uppercase mb-4">
                  Get Started
                </span>
                <h1 className="font-heading text-4xl sm:text-5xl font-bold text-foreground mb-6">
                  {siteConfig.demoForm.heading}
                </h1>
                <p className="text-muted-foreground text-lg leading-relaxed mb-10">
                  {siteConfig.demoForm.description}
                </p>

                {/* Benefits list */}
                <div className="space-y-4 mb-10">
                  {[
                    "Personalized walkthrough of the WellStream Platform",
                    "See real-world use cases for your operation type",
                    "Discuss integration with your existing systems",
                    "Get a custom implementation timeline",
                  ].map((benefit, i) => (
                    <motion.div
                      key={i}
                      initial={{ opacity: 0, x: -10 }}
                      animate={{ opacity: 1, x: 0 }}
                      transition={{ delay: 0.3 + i * 0.1 }}
                      className="flex items-center gap-3"
                    >
                      <CheckCircle2 className="w-5 h-5 text-accent flex-shrink-0" />
                      <span className="text-foreground text-sm">{benefit}</span>
                    </motion.div>
                  ))}
                </div>
              </motion.div>

              {/* Support Contact */}
              <div className="border-t border-border/50 pt-8">
                <h3 className="font-heading font-semibold text-foreground mb-6">Global Support</h3>
                <div className="space-y-4">
                  {siteConfig.supportContact.regions.map((region) => (
                    <div key={region.name} className="flex items-start gap-3">
                      <Globe className="w-5 h-5 text-primary flex-shrink-0 mt-0.5" />
                      <div>
                        <p className="font-medium text-foreground text-sm">{region.name}</p>
                        <p className="text-xs text-muted-foreground">{region.description}</p>
                        <a href={`mailto:${region.email}`} className="text-xs text-primary hover:text-teal-300 transition-colors">
                          {region.email}
                        </a>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Right - Form */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5, delay: 0.2 }}
            >
              {submitted ? (
                <div className="h-full flex items-center justify-center">
                  <div className="text-center p-10 rounded-2xl border border-accent/20 bg-card/30">
                    <div className="w-16 h-16 rounded-full bg-accent/10 flex items-center justify-center mx-auto mb-6">
