    comments: "",
  })
  const [errors, setErrors] = useState<FormErrors>({})
  const [submitted, setSubmitted] = useState(false)

  function validate(): FormErrors {
    const errs: FormErrors = {}
    if (!formData.firstName.trim()) errs.firstName = "First name is required"
    if (!formData.lastName.trim()) errs.lastName = "Last name is required"
    if (!formData.email.trim()) {
      errs.email = "Business email is required"
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      errs.email = "Please enter a valid email address"
    }
    if (!formData.company.trim()) errs.company = "Company is required"
    return errs
  }

  function handleSubmit(e: FormEvent) {
    e.preventDefault()
    const validationErrors = validate()
    setErrors(validationErrors)
    if (Object.keys(validationErrors).length === 0) {
      setSubmitted(true)
    }
  }

  function handleChange(field: keyof FormData, value: string) {
    setFormData((prev) => ({ ...prev, [field]: value }))
    if (errors[field]) {
      setErrors((prev) => {
        const next = { ...prev }
        delete next[field]
        return next
      })
    }
  }

  return (
    <>
      {/* Form Section */}
      <section className="py-20 sm:py-28">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="grid lg:grid-cols-2 gap-12 lg:gap-16">
            {/* Left - Info */}
            <div>
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.5 }}
              >
                <span className="inline-block text-xs font-semibold tracking-widest text-primary uppercase mb-4">
                  Get Started
                </span>
                <h1 className="font-heading text-4xl sm:text-5xl font-bold text-foreground mb-6">
                  {siteConfig.demoForm.heading}
                </h1>
                <p className="text-muted-foreground text-lg leading-relaxed mb-10">
                  {siteConfig.demoForm.description}
                </p>

                {/* Benefits list */}
                <div className="space-y-4 mb-10">
                  {[
                    "Personalized walkthrough of the WellStream Platform",
                    "See real-world use cases for your operation type",
                    "Discuss integration with your existing systems",
                    "Get a custom implementation timeline",
                  ].map((benefit, i) => (
                    <motion.div
                      key={i}
                      initial={{ opacity: 0, x: -10 }}
                      animate={{ opacity: 1, x: 0 }}
                      transition={{ delay: 0.3 + i * 0.1 }}
                      className="flex items-center gap-3"
                    >
                      <CheckCircle2 className="w-5 h-5 text-accent flex-shrink-0" />
                      <span className="text-foreground text-sm">{benefit}</span>
                    </motion.div>
                  ))}
                </div>
              </motion.div>

              {/* Support Contact */}
              <div className="border-t border-border/50 pt-8">
                <h3 className="font-heading font-semibold text-foreground mb-6">Global Support</h3>
                <div className="space-y-4">
                  {siteConfig.supportContact.regions.map((region) => (
                    <div key={region.name} className="flex items-start gap-3">
                      <Globe className="w-5 h-5 text-primary flex-shrink-0 mt-0.5" />
                      <div>
                        <p className="font-medium text-foreground text-sm">{region.name}</p>
                        <p className="text-xs text-muted-foreground">{region.description}</p>
                        <a href={`mailto:${region.email}`} className="text-xs text-primary hover:text-teal-300 transition-colors">
                          {region.email}
                        </a>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Right - Form */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5, delay: 0.2 }}
            >
              {submitted ? (
                <div className="h-full flex items-center justify-center">
                  <div className="text-center p-10 rounded-2xl border border-accent/20 bg-card/30">
                    <div className="w-16 h-16 rounded-full bg-accent/10 flex items-center justify-center mx-auto mb-6">
                      <CheckCircle2 className="w-8 h-8 text-accent" />
                    </div>
                    <h3 className="font-heading text-2xl font-bold text-foreground mb-3">Demo Request Submitted</h3>
                    <p className="text-muted-foreground leading-relaxed">
                      Thank you for your interest in WellStream. Our team will reach out within one business day to schedule your personalized demo.
                    </p>
                  </div>
                </div>
              ) : (
                <form onSubmit={handleSubmit} className="p-6 sm:p-8 rounded-2xl border border-border/50 bg-card/30 space-y-5" noValidate>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                    {/* First Name */}
                    <div>
                      <label htmlFor="firstName" className="block text-sm font-medium text-foreground mb-1.5">
                        First Name <span className="text-destructive">*</span>
                      </label>
                      <input
                        id="firstName"
                        type="text"
                        value={formData.firstName}
                        onChange={(e) => handleChange("firstName", e.target.value)}
                        className={`w-full px-4 py-2.5 rounded-lg bg-background border text-foreground text-sm placeholder:text-muted-foreground/60 focus:outline-none focus:ring-2 focus:ring-primary/50 transition-colors ${
                          errors.firstName ? "border-destructive" : "border-border"
                        }`}
                        placeholder="John"
                      />
                      {errors.firstName && <p className="mt-1 text-xs text-destructive">{errors.firstName}</p>}
                    </div>

                    {/* Last Name */}
                    <div>
                      <label htmlFor="lastName" className="block text-sm font-medium text-foreground mb-1.5">
                        Last Name <span className="text-destructive">*</span>
                      </label>
                      <input
                        id="lastName"
                        type="text"
                        value={formData.lastName}
                        onChange={(e) => handleChange("lastName", e.target.value)}
                        className={`w-full px-4 py-2.5 rounded-lg bg-background border text-foreground text-sm placeholder:text-muted-foreground/60 focus:outline-none focus:ring-2 focus:ring-primary/50 transition-colors ${
                          errors.lastName ? "border-destructive" : "border-border"
                        }`}
                        placeholder="Smith"
                      />
                      {errors.lastName && <p className="mt-1 text-xs text-destructive">{errors.lastName}</p>}
                    </div>
                  </div>

                  {/* Business Email */}
                  <div>
                    <label htmlFor="email" className="block text-sm font-medium text-foreground mb-1.5">
                      Business Email <span className="text-destructive">*</span>
                    </label>
                    <input
                      id="email"
                      type="email"
                      value={formData.email}
                      onChange={(e) => handleChange("email", e.target.value)}
                      className={`w-full px-4 py-2.5 rounded-lg bg-background border text-foreground text-sm placeholder:text-muted-foreground/60 focus:outline-none focus:ring-2 focus:ring-primary/50 transition-colors ${
                        errors.email ? "border-destructive" : "border-border"
                      }`}
                      placeholder="john@company.com"
                    />
                    {errors.email && <p className="mt-1 text-xs text-destructive">{errors.email}</p>}
                  </div>

                  {/* Company */}
                  <div>
                    <label htmlFor="company" className="block text-sm font-medium text-foreground mb-1.5">
                      Company <span className="text-destructive">*</span>
                    </label>
                    <input
                      id="company"
                      type="text"
                      value={formData.company}
                      onChange={(e) => handleChange("company", e.target.value)}
                      className={`w-full px-4 py-2.5 rounded-lg bg-background border text-foreground text-sm placeholder:text-muted-foreground/60 focus:outline-none focus:ring-2 focus:ring-primary/50 transition-colors ${
                        errors.company ? "border-destructive" : "border-border"
                      }`}
                      placeholder="Acme Energy Co."
                    />
                    {errors.company && <p className="mt-1 text-xs text-destructive">{errors.company}</p>}
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                    {/* Phone Number */}
                    <div>
                      <label htmlFor="phone" className="block text-sm font-medium text-foreground mb-1.5">
                        Phone Number
                      </label>
                      <input
                        id="phone"
                        type="tel"
                        value={formData.phone}
                        onChange={(e) => handleChange("phone", e.target.value)}
                        className="w-full px-4 py-2.5 rounded-lg bg-background border border-border text-foreground text-sm placeholder:text-muted-foreground/60 focus:outline-none focus:ring-2 focus:ring-primary/50 transition-colors"
                        placeholder="+1 (555) 000-0000"
                      />
                    </div>

                    {/* Job Title */}
                    <div>
                      <label htmlFor="jobTitle" className="block text-sm font-medium text-foreground mb-1.5">
                        Job Title
                      </label>
                      <input
                        id="jobTitle"
                        type="text"
                        value={formData.jobTitle}
                        onChange={(e) => handleChange("jobTitle", e.target.value)}
                        className="w-full px-4 py-2.5 rounded-lg bg-background border border-border text-foreground text-sm placeholder:text-muted-foreground/60 focus:outline-none focus:ring-2 focus:ring-primary/50 transition-colors"
                        placeholder="VP Operations"
                      />
                    </div>
                  </div>

                  {/* Country */}
                  <div>
                    <label htmlFor="country" className="block text-sm font-medium text-foreground mb-1.5">
                      Country
                    </label>
                    <input
                      id="country"
                      type="text"
                      value={formData.country}
                      onChange={(e) => handleChange("country", e.target.value)}
                      className="w-full px-4 py-2.5 rounded-lg bg-background border border-border text-foreground text-sm placeholder:text-muted-foreground/60 focus:outline-none focus:ring-2 focus:ring-primary/50 transition-colors"
                      placeholder="United States"
                    />
                  </div>

                  {/* Comments */}
                  <div>
                    <label htmlFor="comments" className="block text-sm font-medium text-foreground mb-1.5">
                      Comments
                    </label>
                    <textarea
                      id="comments"
                      rows={4}
                      value={formData.comments}
                      onChange={(e) => handleChange("comments", e.target.value)}
                      className="w-full px-4 py-2.5 rounded-lg bg-background border border-border text-foreground text-sm placeholder:text-muted-foreground/60 focus:outline-none focus:ring-2 focus:ring-primary/50 transition-colors resize-none"
                      placeholder="Tell us about your specific needs..."
                    />
                  </div>

                  {/* Submit */}
                  <button
                    type="submit"
                    className="w-full flex items-center justify-center gap-2 px-8 py-3.5 text-base font-semibold rounded-md bg-primary text-primary-foreground hover:bg-teal-300 transition-colors glow-teal"
                  >
                    <Send className="w-4 h-4" />
                    Submit
                  </button>
                </form>
              )}
            </motion.div>
          </div>
        </div>
      </section>
    </>
  )
}

